def evaluate(expr: str) -> float:
    """
    Evaluates a mathematical expression using the Shunting Yard algorithm
    to convert the expression into Reverse Polish Notation (RPN), 
    followed by evaluation of the RPN expression.
    """

    def precedence(op: str) -> int:
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators: list, values: list):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def to_rpn(expression: str):
        operators = []
        values = []
        i = 0

        while i < len(expression):
            if expression[i].isspace():
                i += 1
                continue

            if expression[i].isdigit() or expression[i] == '.':
                num = ''
                while i < len(expression) and (expression[i].isdigit() or expression[i] == '.'):
                    num += expression[i]
                    i += 1
                values.append(float(num))
                continue

            if expression[i] == '(':
                operators.append(expression[i])
            elif expression[i] == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove '('
            else:
                while (operators and precedence(operators[-1]) >= precedence(expression[i])):
                    apply_operator(operators, values)
                operators.append(expression[i])
            i += 1

        while operators:
            apply_operator(operators, values)

        return values[0]

    return to_rpn(expr)

class TokenType:
    NUMBER = 'NUMBER'
    PLUS = 'PLUS'
    MINUS = 'MINUS'
    MULTIPLY = 'MULTIPLY'
    DIVIDE = 'DIVIDE'
    LPAREN = 'LPAREN'
    RPAREN = 'RPAREN'
    EOF = 'EOF'


class Token:
    def __init__(self, token_type, value=None):
        self.token_type = token_type
        self.value = value


class Lexer:
    def __init__(self, text):
        self.text = text
        self.position = 0
        self.current_char = self.text[self.position]

    def error(self):
        raise Exception('Invalid character')

    def advance(self):
        self.position += 1
        if self.position > len(self.text) - 1:
            self.current_char = None
        else:
            self.current_char = self.text[self.position]

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return Token(TokenType.NUMBER, float(result))

    def get_next_token(self):
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()
            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS)
            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS)
            if self.current_char == '*':
                self.advance()
                return Token(TokenType.MULTIPLY)
            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIVIDE)
            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN)
            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN)
            self.error()
        return Token(TokenType.EOF)


class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self):
        raise Exception('Invalid syntax')

    def eat(self, token_type):
        if self.current_token.token_type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()

    def factor(self):
        token = self.current_token
        if token.token_type == TokenType.NUMBER:
            self.eat(TokenType.NUMBER)
            return token.value
        elif token.token_type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            result = self.expr()
            self.eat(TokenType.RPAREN)
            return result

    def term(self):
        result = self.factor()
        while self.current_token.token_type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            token = self.current_token
            if token.token_type == TokenType.MULTIPLY:
                self.eat(TokenType.MULTIPLY)
                result *= self.factor()
            elif token.token_type == TokenType.DIVIDE:
                self.eat(TokenType.DIVIDE)
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_token.token_type in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token
            if token.token_type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
                result += self.term()
            elif token.token_type == TokenType.MINUS:
                self.eat(TokenType.MINUS)
                result -= self.term()
        return result


def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using a tokenizer and a recursive descent parser.
    This implementation respects operator precedence and handles floating-point numbers.
    """
    lexer = Lexer(expr)
    parser = Parser(lexer)
    return parser.expr()

class Evaluator:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos] if self.text else None

    def error(self):
        raise Exception('Invalid character')

    def advance(self):
        self.pos += 1
        if self.pos < len(self.text):
            self.current_char = self.text[self.pos]
        else:
            self.current_char = None

    def parse_num(self):
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return float(num_str)

    def parse_factor(self):
        if self.current_char == '(':
            self.advance()
            result = self.parse_expr()
            if self.current_char != ')':
                self.error()
            self.advance()  # skip closing parenthesis
            return result
        elif self.current_char.isdigit() or (self.current_char == '.' or (self.current_char == '-' and (self.pos + 1 < len(self.text) and self.text[self.pos + 1].isdigit()))):
            return self.parse_num()
        else:
            self.error()

    def parse_term(self):
        result = self.parse_factor()
        while self.current_char in ('*', '/'):
            if self.current_char == '*':
                self.advance()
                result *= self.parse_factor()
            elif self.current_char == '/':
                self.advance()
                denominator = self.parse_factor()
                if denominator == 0:
                    raise ZeroDivisionError("division by zero")
                result /= denominator
        return result

    def parse_expr(self):
        result = self.parse_term()
        while self.current_char in ('+', '-'):
            if self.current_char == '+':
                self.advance()
                result += self.parse_term()
            elif self.current_char == '-':
                self.advance()
                result -= self.parse_term()
        return result

def evaluate(expr: str) -> float:
    """Evaluates a mathematical expression using a parsing technique based on the recursive descent parser."""
    evaluator = Evaluator(expr)
    return evaluator.parse_expr()

class ArithmeticEvaluator:
    """A simple arithmetic expression evaluator that uses the Shunting Yard algorithm 
    to convert infix expressions to postfix and then evaluates the postfix expression."""

    def __init__(self, expression: str):
        self.expression = expression
        self.pos = 0
        self.current_char = self.expression[self.pos] if self.expression else ''

    def error(self):
        raise Exception("Invalid character in the expression")

    def advance(self):
        self.pos += 1
        if self.pos < len(self.expression):
            self.current_char = self.expression[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)

    def parse_factor(self):
        if self.current_char == '(':
            self.advance()
            result = self.parse_expression()
            self.advance()  # Skip ')'
            return result
        return self.number()

    def parse_term(self):
        result = self.parse_factor()
        while self.current_char is not None and self.current_char in ("*", "/"):
            if self.current_char == '*':
                self.advance()
                result *= self.parse_factor()
            elif self.current_char == '/':
                self.advance()
                divisor = self.parse_factor()
                if divisor == 0:
                    raise ZeroDivisionError("Division by zero")
                result /= divisor
        return result

    def parse_expression(self):
        result = self.parse_term()
        while self.current_char is not None and self.current_char in ("+", "-"):
            if self.current_char == '+':
                self.advance()
                result += self.parse_term()
            elif self.current_char == '-':
                self.advance()
                result -= self.parse_term()
        return result

def evaluate(expr: str) -> float:
    evaluator = ArithmeticEvaluator(expr)
    evaluator.skip_whitespace()
    value = evaluator.parse_expression()
    return value
